      '{\n  "name": "feature-intake",\n  "version": "1.1.0",\n  "description": "Capture client requirements as PRD epics, sub-issues, and GitHub Projects kanban items.",\n  "author": {\n    "name": "Ship Shit Dev",\n    "email": "hello@shipshit.dev",\n    "url": "https://github.com/shipshitdev"\n  },\n  "license": "MIT",\n  "skills": "."\n}\n',
