    path: 'task-prd-creator/plugin.json',
    content:
      '{\n  "name": "task-prd-creator",\n  "version": "1.1.0",\n  "description": "Write well-structured PRDs and tasks. Creates GitHub issues, sub-issues, or local files based on user workflow.",\n  "author": {\n    "name": "Ship Shit Dev",\n    "email": "hello@shipshit.dev",\n    "url": "https://github.com/shipshitdev"\n  },\n  "license": "MIT",\n  "skills": "."\n}\n',
